function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  noStroke();

  // Sky
  brush.fillBleed(0.4); // light blue bleed
  brush.beginShape();
  brush.vertex(0, 0); // top-left
  brush.vertex(400, 0); // top-right
  brush.vertex(400, 100); // top-right hill
  brush.vertex(0, 100); // top-left hill
  brush.endShape(true);

  // Hills
  brush.fill("#e08a72");
  brush.beginShape();
  brush.vertex(0, 150); // top-left hill
  brush.vertex(400, 150); // top-right hill
  brush.vertex(400, 250); // base-right hill
  brush.vertex(0, 250); // base-left hill
  brush.endShape(true);

  // Sunset
  brush.fill("#9c8068");
  brush.beginShape();
  brush.vertex(0, 300); // top-left
  brush.vertex(400, 300); // top-right
  brush.vertex(400, 350); // base-right
  brush.vertex(0, 350); // base-left
  brush.endShape(true);

  // Flag pole on top of the hills
  brush.fill("#756d57");
  brush.beginShape();
  brush.vertex(200, 250); // top of pole
  brush.vertex(200, 300); // base of pole
  brush.endShape(true);
}
```

