  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fillBleed(0.6);
  brush.beginShape();
  brush.vertex(0, 0); // top left
  brush.vertex(400, 0); // top right
  brush.vertex(400, 400); // bottom right
  brush.vertex(0, 400); // bottom left
  brush.endShape(true);
  // Hills
  brush.fill("#98735f");
  brush.beginShape();
  brush.vertex(0, 100); // top left hill
  brush.vertex(400, 100); // top right hill
  brush.vertex(400, 220); // bottom right hill
  brush.vertex(0, 220); // bottom left hill
  brush.endShape(true);
  // Horizon
  brush.fill("#936c4f");
  brush.beginShape();
  brush.vertex(0, 300); // left hill, low
  brush.vertex(400, 300); // right hill, low
  brush.vertex(400, 200); // horizon
  brush.vertex(0, 200); // horizon
  brush.endShape(true);
  // Clouds
  brush.fill("#cce8f8");
  brush.beginShape();
  brush.vertex(50, 120); // top left cloud
  brush.vertex(180, 150); // middle left cloud
  brush.vertex(250, 160); // middle right cloud
  brush.vertex(320, 120); // top right cloud
  brush.endShape(true);
  // Sun
  brush.fill("#f7c256");
  brush.beginShape();
  brush.vertex(200, 140); // top of sun
  brush.vertex(220, 130); // top of sun
  brush.vertex(230, 110); // top of sun
  brush.vertex(210, 100); // top of sun
  brush.endShape(true);
}

