function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");

  // Sky
  brush.fill("#202732");
  brush.fillBleed(0.8); // slightly opalescent
  brush.beginShape();
  brush.vertex(0, 0);    // top left hill
  brush.vertex(400, 0);  // top right hill
  brush.vertex(200, 400); // top center
  brush.endShape(true);

  // Low sun and hills
  brush.fill("#f8f2d7");
  brush.fillBleed(0.5);
  brush.beginShape();
  brush.vertex(0, 200);    // top left hill
  brush.vertex(400, 200);  // top right hill
  brush.vertex(200, 200);  // top center
  brush.endShape(true);

  // Ground
  brush.fill("#3b404e");
  brush.fillBleed(0.8);
  brush.beginShape();
  brush.vertex(0, 200);    // bottom left
  brush.vertex(400, 200);  // bottom right
  brush.vertex(200, 300);  // bottom center
  brush.endShape(true);

  // Grass on the far right
  brush.fill("#5f6c7e");
  brush.fillBleed(0.7);
  brush.beginShape();
  brush.vertex(390, 270);  // first green point
  brush.vertex(390, 290);  // second green point
  brush.vertex(395, 280);  // third green point
  brush.endShape(true);

  // Fake clouds above the top of the horizon
  brush.fill("#ffffff");
  brush.fillBleed(0.3);
  brush.beginShape();
  brush.vertex(0, 200);    // left edge
  brush.vertex(400, 200);  // right edge
  brush.vertex(200, 400);  // top center
  brush.endShape(true);
}
