function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky
  brush.fill("#b8dbd6");
  brush.fillBleed(0.6); // soft, diffuse
  brush.beginShape();
  brush.vertex(0, 0);   // top left
  brush.vertex(400, 0); // top right
  brush.vertex(400, 100); // top right on hills
  brush.vertex(0, 100); // top left on hills
  brush.endShape(true);
  // Clouds
  brush.fill("#e5f2f3");
  brush.fillBleed(0.4); // lighter
  brush.beginShape();
  brush.vertex(0, 120); // left cloud top
  brush.vertex(0, 160); // left cloud bottom
  brush.vertex(100, 160); // top of first hill
  brush.vertex(100, 120); // base of first hill
  brush.vertex(200, 160); // top of second hill
  brush.vertex(200, 120); // base of second hill
  brush.endShape(true);
  // Hills
  brush.fill("#a3c8b2");
  brush.fillBleed(0.6); // mid tone, very soft
  brush.beginShape();
  brush.vertex(0, 200); // base of first hill
  brush.vertex(0, 300); // middle of first hill
  brush.vertex(400, 300); // middle of first hill
  brush.vertex(400, 200); // base of first hill
  brush.endShape(true);
  // Sun
  brush.fill("#ffb353"); // orange/amber
  brush.beginShape();
  brush.vertex(200, 180); // top of sun
  brush.vertex(200, 150); // top of sun
  brush.vertex(220, 150); // top right
  brush.vertex(180, 150); // top left
  brush.endShape(true);
}
