function setup() {
  createCanvas(400, 400, WEBGL);
  brush.scaleBrushes(2);
  noLoop();
}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Sky: soft light grey
  brush.fill("#c8d0cd");
  brush.beginShape();
  brush.vertex(0, 100); // top left
  brush.vertex(200, 100); // top middle
  brush.vertex(400, 100); // top right
  brush.endShape(true);

  // Clouds: white with light grey halftones
  brush.fill("#fff2f0");
  brush.beginShape();
  brush.vertex(0, 120);
  brush.vertex(200, 130);
  brush.vertex(400, 120);
  brush.endShape(true);

  // Ground: darker grey, hint of soft tan
  brush.fill("#807066");
  brush.beginShape();
  brush.vertex(0, 300); // top left
  brush.vertex(200, 350); // top middle
  brush.vertex(400, 300); // top right
  brush.endShape(true);

  // Hills: light tan
  brush.fill("#c5a185");
  brush.beginShape();
  brush.vertex(0, 380); // top left
  brush.vertex(200, 430); // top middle
  brush.vertex(400, 380); // top right
  brush.endShape(true);

  // Sun: radiant orange with a luminous edge
  brush.fill("#f69a26");
  brush.beginShape();
  brush.vertex(200, 280); // top
  brush.vertex(200, 230); // top right
  brush.vertex(220, 220); // top right
  brush.vertex(180, 220); // top left
  brush.endShape(true);

  // Hills with burnt orange
  brush.fill("#f49051");
  brush.beginShape();
  brush.vertex(0, 390); // top left
  brush.vertex(200, 440); // top middle
  brush.vertex(400, 390); // top right
  brush.endShape(true);
}
