  brush.beginShape();
  brush.vertex(0, 150);        // top left hill
  brush.vertex(400, 150);      // top right hill
  brush.vertex(400, 250);      // top right
  brush.vertex(0, 250);       // top left
  brush.endShape(true);

  // Ground
  brush.fill("#34495e", 180);  // dark blue
  brush.beginShape();
  brush.vertex(0, 300);        // top left hill
  brush.vertex(400, 300);       // top right hill
  brush.vertex(400, 350);       // top right plain
  brush.vertex(0, 350);        // top left plain
  brush.endShape(true);

  // Hills
  brush.fill("#2c3e50", 200);  // dark green
  brush.beginShape();
  brush.vertex(0, 400);        // top left hill
  brush.vertex(400, 400);       // top right hill
  brush.vertex(400, 430);       // top right plain
  brush.vertex(0, 430);        // top left plain
  brush.endShape(true);

  // Dust
